from __future__ import annotations

from pathlib import Path


ROOT = Path(__file__).resolve().parents[2]
TARGET = ROOT / "minecraft_mod_ai" / "custom_module_generator.py"
TEST = ROOT / "tests" / "test_custom_module_host_grounding_contract.py"


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected exactly one match, found {count}")
    return text.replace(old, new, 1)


def main() -> None:
    text = TARGET.read_text(encoding="utf-8")

    text = replace_once(
        text,
        "from .complete_spec import ProductionModule\n",
        "from .complete_spec import ProductionModule\n"
        "from .host_grounding import build_coder_grounding\n",
        "host grounding import",
    )

    old_fast = '''        # ProjectIndex below already supplies fresh, exact, SHA-bound source evidence.\n        # Keep the normal custom generation path to one model decode and materialize\n        # model-callable RAG only if host validation actually rejects that response.\n        self.router.bind_agent_workspace(root.parent, require_fresh_evidence=True)\n\n        query = json.dumps(\n            {\n                "module_id": module.module_id,\n                "kind": module.kind,\n                "config": module.config,\n                "depends_on": module.depends_on,\n            },\n            ensure_ascii=False,\n            sort_keys=True,\n        )\n        # Fast Path check: bypass heavy multi-pass source scanning in Fast Mode\n        is_fast_path = self.fast_mode\n\n        if is_fast_path:\n            print(\n                "🚀 [Fast-Path] 소스 정밀 RAG 탐색 스킵 (Fast Path Express 구동 중)...",\n                flush=True,\n            )\n            observation_ledger = {\n                "receipt": "fast_path_express",\n                "observations": [],\n            }\n            observation_pages = [\n                {"page_index": 0, "page_count": 1, "records": []}\n            ]\n        else:\n            project_context_budget = min(\n                self.policy.model_context_bytes,\n                12 * 1024,\n            )\n            observation_ledger: dict[str, Any] | None = None\n            last_snapshot_error: ValueError | None = None\n            # A deterministic generator may finish while the LLM lane is preparing\n            # its context. Keep the lanes overlapped, but never consume a stale\n            # ProjectIndex snapshot. Rebuild a bounded number of times instead of\n            # serializing all generation behind one global filesystem lock.\n            for snapshot_attempt in range(3):\n                try:\n                    observation_ledger = _collect_initial_observations(\n                        self.router,\n                        index,\n                        query=query,\n                        byte_budget=project_context_budget,\n                    )\n                    break\n                except ValueError as exc:\n                    if not _is_stale_project_index_error(exc):\n                        raise\n                    last_snapshot_error = exc\n                    index = ProjectIndex(root, policy=self.policy)\n                    self._cached_index = index\n                    self._cached_root = root\n                    print(\n                        "↻ [CustomModule] ProjectIndex snapshot changed during "\n                        f"parallel generation; refreshed context ({snapshot_attempt + 1}/3).",\n                        flush=True,\n                    )\n            if observation_ledger is None:\n                raise CustomModuleGenerationError(\n                    "Project source kept changing while custom-module context was "\n                    "being captured; refusing to generate from a stale snapshot. "\n                    f"Last error: {last_snapshot_error}"\n                )\n            observation_pages = _observation_context_pages(\n                observation_ledger,\n                query=query,\n                byte_budget=project_context_budget,\n            )\n'''
    new_fast = '''        # ProjectIndex and the approved research ledger are mandatory host-owned\n        # grounding. Model-callable RAG remains a supplemental repair path only.\n        self.router.bind_agent_workspace(root.parent, require_fresh_evidence=True)\n\n        query = json.dumps(\n            {\n                "module_id": module.module_id,\n                "kind": module.kind,\n                "config": module.config,\n                "depends_on": module.depends_on,\n            },\n            ensure_ascii=False,\n            sort_keys=True,\n        )\n        # Fast mode may reduce the evidence byte budget, but it may not skip the\n        # baseline exact-source grounding contract.\n        project_context_budget = min(\n            self.policy.model_context_bytes,\n            (4 if self.fast_mode else 12) * 1024,\n        )\n        if self.fast_mode:\n            print(\n                "🚀 [Fast-Path] host exact-source grounding limited to 4 KiB.",\n                flush=True,\n            )\n        observation_ledger: dict[str, Any] | None = None\n        last_snapshot_error: ValueError | None = None\n        # A deterministic generator may finish while the LLM lane is preparing\n        # its context. Keep the lanes overlapped, but never consume a stale\n        # ProjectIndex snapshot. Rebuild a bounded number of times instead of\n        # serializing all generation behind one global filesystem lock.\n        for snapshot_attempt in range(3):\n            try:\n                observation_ledger = _collect_initial_observations(\n                    self.router,\n                    index,\n                    query=query,\n                    byte_budget=project_context_budget,\n                )\n                break\n            except ValueError as exc:\n                if not _is_stale_project_index_error(exc):\n                    raise\n                last_snapshot_error = exc\n                index = ProjectIndex(root, policy=self.policy)\n                self._cached_index = index\n                self._cached_root = root\n                print(\n                    "↻ [CustomModule] ProjectIndex snapshot changed during "\n                    f"parallel generation; refreshed context ({snapshot_attempt + 1}/3).",\n                    flush=True,\n                )\n        if observation_ledger is None:\n            raise CustomModuleGenerationError(\n                "Project source kept changing while custom-module context was "\n                "being captured; refusing to generate from a stale snapshot. "\n                f"Last error: {last_snapshot_error}"\n            )\n        observation_pages = _observation_context_pages(\n            observation_ledger,\n            query=query,\n            byte_budget=project_context_budget,\n        )\n'''
    text = replace_once(text, old_fast, new_fast, "mandatory exact-source grounding")

    old_research = '''        research_context = select_module_research_context(\n            research_modules,\n            query=query,\n            byte_budget=8 * 1024,\n        )\n        base_request = {\n'''
    new_research = '''        research_context = select_module_research_context(\n            research_modules,\n            query=query,\n            byte_budget=8 * 1024,\n        )\n        host_grounding = build_coder_grounding(\n            module_kind=module.kind,\n            source_observation_receipt=observation_ledger["receipt"],\n            research_context=research_context,\n            minecraft_version=minecraft_version,\n            loader=loader,\n            mappings=mappings,\n        )\n        base_request = {\n'''
    text = replace_once(text, old_research, new_research, "pre-coder grounding build")

    text = replace_once(
        text,
        '            "research_context": research_context,\n            "output_contract": {\n',
        '            "research_context": research_context,\n'
        '            "host_grounding": host_grounding,\n'
        '            "output_contract": {\n',
        "grounding request field",
    )

    old_prompt = '''                            "already supplied fresh exact source observations and reviewed "\n                            "research_context for this bounded first pass. Use them directly; "\n                            "do not repeat retrieval unless host validation rejects the result "\n                            "and explicitly enters evidence-backed repair. When code output for "\n'''
    new_prompt = '''                            "already supplied fresh exact source observations and reviewed "\n                            "research_context for this bounded first pass. host_grounding is a "\n                            "code-owned contract proving that baseline ProjectIndex RAG, approved "\n                            "research RAG, Skill selection, and role-scoped MCP routing were "\n                            "resolved before this coder decode. Baseline grounding is not an "\n                            "optional model decision. Use the supplied evidence directly; do not "\n                            "repeat retrieval unless host validation rejects the result and "\n                            "explicitly enters evidence-backed repair. When code output for "\n'''
    text = replace_once(text, old_prompt, new_prompt, "first coder grounding prompt")

    TARGET.write_text(text, encoding="utf-8")

    TEST.write_text(
        '''from __future__ import annotations\n\nimport inspect\n\nfrom minecraft_mod_ai.agent_roles import skills_for_model_role\nfrom minecraft_mod_ai.custom_module_generator import CustomModuleGenerator\nfrom minecraft_mod_ai.host_grounding import build_coder_grounding\n\n\ndef _grounding(kind: str = "networking") -> dict:\n    return build_coder_grounding(\n        module_kind=kind,\n        source_observation_receipt={\n            "schema_version": "mmm/source-observation-receipt-v1",\n            "project_sha256": "sha256:" + "1" * 64,\n            "query_sha256": "sha256:" + "2" * 64,\n            "observation_count": 3,\n            "observations_sha256": "sha256:" + "3" * 64,\n        },\n        research_context={\n            "schema_version": "mmm/module-research-context-v1",\n            "corpus_sha256": "sha256:" + "4" * 64,\n            "ledger_fact_count": 8,\n            "selected_record_count": 2,\n            "selected_fact_count": 2,\n            "selected_facts_sha256": "sha256:" + "5" * 64,\n            "omitted_fact_count": 6,\n        },\n        minecraft_version="1.20.1",\n        loader="fabric",\n        mappings="1.20.1+build.1",\n    )\n\n\ndef test_host_grounding_is_mandatory_and_role_scoped() -> None:\n    grounding = _grounding()\n    policy = grounding["policy"]\n    assert policy["resolved_before_first_coder_decode"] is True\n    assert policy["baseline_grounding_owned_by_host"] is True\n    assert policy["baseline_grounding_optional_for_model"] is False\n    assert policy["model_tool_choice_required_for_baseline"] is False\n    assert policy["retrieved_context_can_authorize"] is False\n    assert "ground-production-with-live-evidence" in grounding["required_skills"]\n    assert "patch-existing-project" in grounding["required_skills"]\n    assert "generate-gui-networking" in grounding["required_skills"]\n    assert set(grounding["required_skills"]).issubset(\n        set(skills_for_model_role("coder"))\n    )\n    assert grounding["reviewed_mcp_servers"]\n    assert grounding["evidence_bindings"]["project_exact_rag"]["request_field"] == (\n        "relevant_context"\n    )\n    assert grounding["evidence_bindings"]["approved_research_rag"]["request_field"] == (\n        "research_context"\n    )\n\n\ndef test_module_kind_selects_specialized_grounding_skill() -> None:\n    assert "generate-worldgen" in _grounding("dimension")["required_skills"]\n    assert "generate-datagen" in _grounding("loot")["required_skills"]\n    assert "generate-audio" in _grounding("audio")["required_skills"]\n    assert "generate-fabric-core" in _grounding("block")["required_skills"]\n\n\ndef test_generator_resolves_grounding_before_first_coder_decode() -> None:\n    source = inspect.getsource(CustomModuleGenerator.generate)\n    grounding_index = source.index("host_grounding = build_coder_grounding(")\n    first_decode_index = source.index("self.router.generate_text(")\n    assert grounding_index < first_decode_index\n    assert '\"host_grounding\": host_grounding' in source\n    assert "enable_tools=False" in source\n    fast_guard = source.index("project_context_budget = min(")\n    exact_observation = source.index("_collect_initial_observations(")\n    assert fast_guard < exact_observation < grounding_index\n    assert "fast_path_express" not in source\n''',
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
